using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;

namespace MacroExecute
{
    internal static class BuildingTests
    {
        private static IEnumerable<Control> All(Control root){foreach(Control child in root.Controls){yield return child;foreach(var nested in All(child))yield return nested;}}
        private static void Check(bool value,string message){if(!value)throw new Exception(message);}
        private static void Click(Button button){typeof(Button).GetMethod("OnClick",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(button,new object[]{EventArgs.Empty});}
        public static void Run(Action<string,Action> test,string directory)
        {
            test("Duration units preserve exact milliseconds across all ranges",delegate{foreach(int value in new[]{0,1,10,999,1000,12345,86400000})using(var input=new DurationInput(value,0,86400000,true)){Check(input.Milliseconds==value,"Initial seconds conversion lost precision.");input.SetSeconds(false);Check(input.Milliseconds==value,"Switch to milliseconds changed value.");input.SetSeconds(true);Check(input.Milliseconds==value,"Switch back changed value.");}using(var polling=new DurationInput(10,10,60000,false)){polling.SetSeconds(true);Check(polling.Milliseconds==10,"Minimum polling precision lost.");}});
            test("Duration unit switches stay visible and legible in the guided editor",delegate{using(var editor=new StepEditor(new Step{Kind=ActionKind.Delay},directory)){HeadlessUi.Render(editor,Path.Combine(directory,"duration-units.png"));foreach(var button in All(editor).OfType<Button>().Where(b=>b.Text=="ms"||b.Text=="s")){Check(button.Bottom<=button.Parent.ClientSize.Height&&button.Right<=button.Parent.ClientSize.Width&&button.Height>=24&&button.Width>=30,"Unit clipped: "+button.Text+" bounds="+button.Bounds+" parent="+button.Parent.ClientSize);}}});
            test("Guided delay saves seconds as exact original-schema milliseconds",delegate{using(var editor=new StepEditor(new Step{Kind=ActionKind.Delay,DelayMs=1234},directory)){var inputs=All(editor).OfType<DurationInput>().ToArray();Check(inputs.Length==2&&inputs[0].Milliseconds==1234,"Duration controls missing.");inputs[0].Milliseconds=2501;Click(All(editor).OfType<Button>().First(b=>b.Text=="Save step"));Check(editor.Value.DelayMs==2501&&editor.DialogResult==DialogResult.OK&&!editor.Visible,"Saved duration differs from display.");}});
            test("Image waiting controls disable irrelevant timeout and polling",delegate{using(var editor=new StepEditor(Samples.Nested().Steps[0],directory)){var fields=All(editor).OfType<DurationInput>().ToArray();Check(fields.Length==2&&!fields[0].Enabled&&!fields[1].Enabled,"Check-once image exposes active wait settings.");var wait=All(editor).OfType<CheckBox>().First(c=>c.Text=="Wait before deciding the IF branch");wait.Checked=true;Check(fields[0].Enabled&&fields[1].Enabled,"Timed waiting cannot be configured.");All(editor).OfType<CheckBox>().First(c=>c.Text=="Wait forever until Stop").Checked=true;Check(!fields[0].Enabled&&fields[1].Enabled,"Infinite waiting still enables a finite timeout.");}});
            test("Keyboard combinations press modifiers then release them in reverse",delegate{var steps=KeyboardChord.Create(Keys.Control|Keys.Shift|Keys.Alt|Keys.Delete);Check(steps.Select(s=>s.Kind).SequenceEqual(new[]{ActionKind.KeyDown,ActionKind.KeyDown,ActionKind.KeyDown,ActionKind.KeyPress,ActionKind.KeyUp,ActionKind.KeyUp,ActionKind.KeyUp}),"Wrong shortcut sequence.");Check(steps.Select(s=>s.KeyCode).SequenceEqual(new[]{17,16,18,46,18,16,17})&&steps[3].Extended,"Modifiers/extended key wrong.");Storage.Validate(new Macro{Steps=steps});Check(KeyboardChord.Create(Keys.A).Count==1,"Simple key expanded unnecessarily.");foreach(var invalid in new[]{Keys.None,Keys.ControlKey,Keys.LWin}){bool rejected=false;try{KeyboardChord.Create(invalid);}catch(ArgumentException){rejected=true;}Check(rejected,"Invalid shortcut accepted.");}});
            test("Shortcut builder insertion is one undoable ordinary-step edit",delegate{using(var form=new MainForm(new Macro(),null,false,false,true)){HeadlessUi.Render(form,Path.Combine(directory,"chord-insert.png"));form.InsertChordHeadless(Keys.Control|Keys.C);Check(form.DocumentHeadless().Steps.Count==3,"Shortcut not inserted.");Click(All(form).OfType<Button>().First(b=>b.Text=="↶ Undo"));Check(form.DocumentHeadless().Steps.Count==0,"Shortcut undo left a held modifier step.");Click(All(form).OfType<Button>().First(b=>b.Text=="↷ Redo"));Check(form.DocumentHeadless().Steps.Count==3&&!form.Visible,"Shortcut redo wrong.");}});
            test("Shortcut search offers composer without claiming no matching actions",delegate{using(var form=new MainForm(new Macro(),null,false,false,true)){form.SearchHeadless("ctrl");Check(All(form).OfType<Button>().Any(b=>b.AccessibleName=="Add Keyboard shortcut")&&!All(form).OfType<Label>().Any(l=>l.Text.StartsWith("No matching actions")),"Composer search is contradictory.");}});
            test("Macro review validates images and identifies their source row without running",delegate{var broken=new Macro{Steps=new List<Step>{new Step{Kind=ActionKind.IfImage},new Step{Kind=ActionKind.Else},new Step{Kind=ActionKind.EndIf}}};var issues=MacroReview.Check(broken,directory);Check(issues.Any(i=>i.Error&&i.Step==0)&&issues.Any(i=>!i.Error&&i.Step==0),"Missing image or empty-branch guidance absent.");Check(!MacroReview.Check(Samples.Nested(),directory).Any(i=>i.Error),"Embedded-image sample rejected.");broken.Steps[0].Enabled=broken.Steps[1].Enabled=broken.Steps[2].Enabled=false;Check(!MacroReview.Check(broken,directory).Any(i=>i.Error),"Disabled reference blocks review.");});
            test("Macro review catches structural errors and provides hidden jump controls",delegate{var issues=MacroReview.Check(new Macro{Steps=new List<Step>{new Step{Kind=ActionKind.EndIf}}},directory);Check(issues.Any(i=>i.Error&&i.Step==0),"Unmatched end not attributed to its source row.");using(var form=new MacroReviewForm(new[]{new ReviewItem{Step=2,Error=true,Message="Fix reference image"}})){HeadlessUi.Render(form,Path.Combine(directory,"review-jump.png"));var list=All(form).OfType<ListView>().Single();list.Items[0].Selected=true;Click(All(form).OfType<Button>().First(b=>b.Text=="Go to step"));Check(form.SelectedStep==2&&form.DialogResult==DialogResult.OK&&!form.Visible,"Review cannot navigate to its issue.");}});
            test("New actions and shortcut sequences inherit a disabled containing block",delegate{var macro=Samples.Nested();foreach(var step in macro.Steps)step.Enabled=false;using(var form=new MainForm(macro,null,false,false,true)){HeadlessUi.Render(form,Path.Combine(directory,"disabled-insert.png"));form.SelectHeadlessStep(0);form.InsertChordHeadless(Keys.Control|Keys.V);Check(form.DocumentHeadless().Steps.Skip(1).Take(3).All(s=>!s.Enabled),"Inserted shortcut escaped disabled scope.");}});
            test("Empty recording creates no undo entry while real recording is atomic",delegate{using(var form=new MainForm(new Macro(),null,false,false,true)){HeadlessUi.Render(form,Path.Combine(directory,"recording-commit.png"));form.RecordingHeadless(new List<Step>(),0,true);Check(!All(form).OfType<Button>().First(b=>b.Text=="↶ Undo").Enabled,"Empty recording changed history.");form.RecordingHeadless(new List<Step>{new Step{Kind=ActionKind.Note,Text="recorded"}},0,false);Check(!form.DocumentHeadless().Steps[0].Enabled,"Recording ignored disabled destination.");Click(All(form).OfType<Button>().First(b=>b.Text=="↶ Undo"));Check(form.DocumentHeadless().Steps.Count==0,"Recording undo failed.");}});
            test("Guided key capture does not silently drop combination modifiers",delegate{using(var editor=new StepEditor(new Step{Kind=ActionKind.KeyPress,KeyCode=(int)Keys.A},directory)){var box=All(editor).OfType<TextBox>().First(t=>t.AccessibleName=="Press a key here");typeof(Control).GetMethod("OnKeyDown",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(box,new object[]{new KeyEventArgs(Keys.Control|Keys.C)});Check(editor.Value.KeyCode==(int)Keys.A&&All(editor).OfType<Label>().Any(l=>l.Text.Contains("Use Keyboard shortcut")),"Modifier combination was silently changed into a single key.");}});
            test("Recent workflow opens from welcome without running it",delegate{string path=Path.Combine(directory,"recent.mmacro.json");Storage.Save(path,new Macro{Name="Recent test",Steps=new List<Step>{new Step{Kind=ActionKind.Note,Text="Never executed"}}});var prefs=new Preferences{AccentStyle="Aftershock",DarkMode=true,RecentFiles=new[]{path}};using(var form=new MainForm(new Macro(),null,false,false,true,prefs)){HeadlessUi.Render(form,Path.Combine(directory,"recent-welcome.png"));Click(All(form).OfType<Button>().First(b=>b.AccessibleName=="Open recent recent.mmacro.json"));Check(form.DocumentHeadless().Name=="Recent test"&&form.DocumentHeadless().Steps.Count==1&&!form.Visible,"Recent workflow not loaded safely.");}});
        }
    }
}
